function initTabNavigation(){const t=document.querySelectorAll(".mtt-tab"),e=document.querySelectorAll(".mtt-section");t.forEach(n=>{n.addEventListener("click",()=>{const i=n.dataset.tab;t.forEach(t=>t.classList.remove("active")),e.forEach(t=>t.classList.remove("active")),n.classList.add("active");const a=document.getElementById(i);a&&(a.classList.add("active"),a.scrollIntoView({behavior:"smooth",block:"start"}))})})}function initThemeToggle(){const t=document.getElementById("theme-toggle");if(!t)return;updateThemeIcon(localStorage.getItem("theme")||"dark"),t.addEventListener("click",()=>{const t=document.body;t.classList.contains("light-theme")?(t.classList.remove("light-theme"),localStorage.setItem("theme","dark"),updateThemeIcon("dark")):(t.classList.add("light-theme"),localStorage.setItem("theme","light"),updateThemeIcon("light"))})}function updateThemeIcon(t){const e=document.getElementById("theme-toggle");e&&(e.textContent="light"===t?"🌙":"☀️")}function initMobileMenu(){const t=document.getElementById("menu-toggle"),e=document.getElementById("nav-menu");t&&e&&(t.addEventListener("click",()=>{const n="true"===t.getAttribute("aria-expanded");t.setAttribute("aria-expanded",!n),e.classList.toggle("active")}),document.addEventListener("click",n=>{t.contains(n.target)||e.contains(n.target)||(e.classList.remove("active"),t.setAttribute("aria-expanded","false"))}))}function initScrollAnimations(){const t=new IntersectionObserver(e=>{e.forEach(e=>{e.isIntersecting&&(e.target.classList.add("animate-in"),t.unobserve(e.target))})},{threshold:.1,rootMargin:"0px 0px -50px 0px"});document.querySelectorAll(".fact-item, .gallery-item").forEach(e=>{e.classList.add("animate-on-scroll"),t.observe(e)})}document.addEventListener("DOMContentLoaded",()=>{initTabNavigation(),initThemeToggle(),initMobileMenu(),initScrollAnimations()});export{initTabNavigation,initThemeToggle,initMobileMenu,initScrollAnimations};